BEGIN TRANSACTION;

UPDATE Production.ProductInventory
SET Quantity = Quantity - 10
WHERE ProductID = 1 AND LocationID = 1;

UPDATE Production.ProductInventory
SET Quantity = Quantity + 10
WHERE ProductID = 1 AND LocationID = 2;

COMMIT TRANSACTION;
-- Both UPDATEs succeed together, or neither takes effect.

-- Right choice for this scenario: physically stored, real statistics, indexable
CREATE TABLE #ActiveOrders (OrderID INT, CustomerID INT, OrderTotal MONEY);

INSERT INTO #ActiveOrders
SELECT OrderID, CustomerID, OrderTotal FROM Sales.SalesOrderHeader WHERE Status = 'Active';

CREATE INDEX IX_Temp_CustomerID ON #ActiveOrders (CustomerID);
-- Now reused across three statements with an index the optimizer can actually use.

-- Must be run while connected to the TARGET DATABASE itself, not master
EXECUTE sp_set_database_firewall_rule
    @name = N'PartnerOfficeRange',
    @start_ip_address = '203.0.113.10',
    @end_ip_address = '203.0.113.20';

-- Verify it was created, from the same database connection
SELECT * FROM sys.database_firewall_rules;

USE msdb;
EXEC sp_add_job @job_name = N'Nightly Index Maintenance';

EXEC sp_add_jobstep
    @job_name = N'Nightly Index Maintenance',
    @step_name = N'Rebuild Fragmented Indexes',
    @step_id = 1,
    @subsystem = N'TSQL',
    @command = N'EXEC dbo.RebuildFragmentedIndexes;',
    @on_success_action = 3; -- go to next step

EXEC sp_add_jobstep
    @job_name = N'Nightly Index Maintenance',
    @step_name = N'Update Statistics',
    @step_id = 2,
    @subsystem = N'TSQL',
    @command = N'EXEC sp_updatestats;';

EXEC sp_add_schedule
    @schedule_name = N'Nightly1AM',
    @freq_type = 4,            -- daily
    @freq_interval = 1,
    @active_start_time = 010000;

EXEC sp_attach_schedule
    @job_name = N'Nightly Index Maintenance',
    @schedule_name = N'Nightly1AM';

EXEC sp_add_jobserver
    @job_name = N'Nightly Index Maintenance',
    @server_name = N'(local)';

-- SQL Server
CREATE LOGIN rpt_reader WITH PASSWORD = 'StrongPassword1!';
USE ReportingDB;
CREATE USER rpt_reader FOR LOGIN rpt_reader;
GRANT SELECT ON SCHEMA::reporting TO rpt_reader;

-- PostgreSQL
CREATE ROLE rpt_reader LOGIN PASSWORD 'StrongPassword1!';
GRANT USAGE ON SCHEMA reporting TO rpt_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA reporting TO rpt_reader;

-- Oracle (user = schema; no separate mapping step)
CREATE USER rpt_reader IDENTIFIED BY StrongPassword1;
GRANT CREATE SESSION TO rpt_reader;
GRANT SELECT ON reporting_owner.sales_summary TO rpt_reader;

-- NON-SARGABLE: forces a full scan even with an index on OrderDate
WHERE YEAR(OrderDate) = 2013;

-- SARGABLE rewrite: the column itself is untouched, index can be used
WHERE OrderDate >= '2013-01-01' AND OrderDate < '2014-01-01';

-- Likely cause: SELECT * defeats the covering index
SELECT * FROM Sales.SalesOrderDetail WHERE ProductID = 712;

-- Fix: name only the columns the covering index actually includes
SELECT SalesOrderID, ProductID, OrderQty, UnitPrice
FROM Sales.SalesOrderDetail WHERE ProductID = 712;

db.orders.find({ customerId: 48213, status: 'shipped' }).explain('executionStats');
// Before: winningPlan.stage = 'COLLSCAN', totalDocsExamined ~= entire collection

db.orders.createIndex({ customerId: 1, status: 1 });

db.orders.find({ customerId: 48213, status: 'shipped' }).explain('executionStats');
// After: winningPlan.stage = 'IXSCAN', totalDocsExamined ~= nReturned
